import hashlib
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']

def task_func(hex_keys=KEYS, seed=42):
    for key in hex_keys:
        if not isinstance(key, str):
            raise ValueError("Invalid hexadecimal string")
        try:
            raw = bytes.fromhex(key)
        except ValueError:
            raise ValueError("Invalid hexadecimal string")
        if len(raw) != 4:
            raise ValueError("Invalid hexadecimal string")

    rng = random.Random(seed)
    chosen_key = rng.choice(hex_keys)
    float_value = struct.unpack("!f", bytes.fromhex(chosen_key))[0]

    return hashlib.md5(str(float_value).encode("utf-8")).hexdigest()
